/// Derive a human title from the chosen file/folder path (its stem), e.g.
/// `"…/My Novel.skrib"` → `"My Novel"`. Falls back to `"Untitled"`.
fn title_from_file_name(file_name: &str) -> String {
    Path::new(file_name)
        .file_stem()
        .map(|s| s.to_string_lossy().into_owned())
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| "Untitled".to_string())
}

impl NewWorkUseCase {
    pub fn new(uow_factory: Box<dyn NewWorkUnitOfWorkFactoryTrait>) -> Self {
        NewWorkUseCase { uow_factory }
    }

    pub fn execute(&mut self, dto: &NewWorkDto) -> Result<()> {
        // A work must have a destination on disk — an empty path would create an
        // in-memory work that the follow-up save silently drops (no file, no
        // error). Reject it here so the caller sees a real failure. The UI also
        // guards this (the New Work dialog disables "Create" until name +
        // location are valid); this is the backend backstop for scripts/API.
        if dto.file_name.trim().is_empty() {
            anyhow::bail!("new work has no file name — choose a name and location");
        }

        let mut uow = self.uow_factory.create();
        uow.begin_transaction()?;

        // Phase 2 (see the multi-Work migration design doc §8): creating a work
        // no longer closes any other currently-open Work first — a second
        // simultaneously-open Work stays open. `Root.works` is an append
        // (Phase 0), so creating this Work cannot disturb another Work's rows.
        //
        // Pinned by `frontend::tests::multi_work_scoping_test::
        // new_work_leaves_every_other_open_work_intact`, which asserts a
        // previously-open Work survives a `new_work` call untouched — see that
        // test for the both-directions proof.
        let now = chrono::Utc::now();
        let title = title_from_file_name(&dto.file_name);
        let labels = TemplateLabels::from_list(&dto.labels);

        // Every Work owns exactly one punctuation row, created BEFORE the Work
        // so the Work can be built with its real id.
        //
        // Not a detail of style: a one-to-one field seeds its junction at
        // create time, so leaving a placeholder 0 here makes the second
        // project of a session fail outright with "SmartPunctuation 0 is
        // already referenced by Work 1" — the generated uniqueness check
        // doing exactly its job. `..Default::default()` below would have
        // filled that 0 in silently.
        let smart_punctuation = uow.create_orphan_smart_punctuation(&SmartPunctuation {
            created_at: now,
            updated_at: now,
            // Every rule off, and `override_app_default` off above all: a new
            // project follows the app-level preference until someone
            // deliberately gives it a house style of its own.
            override_app_default: false,
            dashes: false,
            ellipsis: false,
            quotes: false,
            quote_style: common::entities::QuoteStyle::LocaleDefault,
            pre_punctuation_spacing: false,
            dialogue_marker: false,
            ..Default::default()
        })?;

        // The Work (with a fresh, stable identity).
        let work = uow.create_orphan_work(&Work {
            created_at: now,
            updated_at: now,
            title: title.clone(),
            // Optional — an empty name is a legal, common state (the New Work
            // field may simply be left blank), and the compiler omits it.
            author_name: dto.author_name.clone(),
            dict_language: dto.language.clone(),
            unique_id: skrib_format::new_unique_id(),
            // The per-project chapter storage mode — same source as the template's
            // per-chapter encoding, so the Create menu keeps matching the book.
            chapter_mode: if dto.chapter_scene_mode {
                ChapterMode::Flat
            } else {
                ChapterMode::Folder
            },
            // Off by default for every new project — a writer opts a specific
            // project into custom replacements explicitly, never inherits it.
            custom_replacement_rules_enabled: false,
            smart_punctuation: smart_punctuation.id,
            ..Default::default()
        })?;

        // Template subtree: binders → items → content (already model-valid).
        let mut binder_ids: Vec<EntityId> = Vec::new();
        let paratexts = ParatextPlan {
            front: dto.paratext_front.clone(),
            back: dto.paratext_back.clone(),
        };
        for tb in build_template_with_paratexts(
            dto.template_kind.clone(),
            &title,
            &labels,
            dto.chapter_scene_mode,
            &paratexts,
        ) {
            // A real uid per row, NOT the `Default` nil.
            //
            // `BinderTreeKey` is `Binder(uid)` / `Item(uid)`, and `TreeDataSlice` builds
            // its parent→children map keyed by that. Leaving these nil gave every binder
            // and every item in a new project the SAME key, so the child list of that one
            // key contained its own row and `flatten_node` recursed until the stack
            // overflowed — creating a project from the Launcher aborted the process
            // outright. Reading a project back was never affected, because `heal_uid`
            // replaces a nil uid on load; only freshly minted, never-saved rows were.
            let binder = uow.create_orphan_binder(&Binder {
                created_at: now,
                updated_at: now,
                uid: common::uid::new_uid(),
                name: tb.name,
                activated: tb.activated,
                ..Default::default()
            })?;
            let mut item_ids: Vec<EntityId> = Vec::new();
            for ti in tb.items {
                let mut content_ids: Vec<EntityId> = Vec::new();
                for (role, data) in ti.contents {
                    let content = uow.create_orphan_content(&Content {
                        created_at: now,
                        updated_at: now,
                        activated: true,
                        role,
                        data,
                        ..Default::default()
                    })?;
                    content_ids.push(content.id);
                }
                let item = uow.create_orphan_binder_item(&BinderItem {
                    created_at: now,
                    updated_at: now,
                    uid: common::uid::new_uid(),
                    title: ti.title,
                    role: ti.role,
                    sub_role: ti.sub_role,
                    is_exportable: ti.is_exportable,
                    indent: ti.indent,
                    activated: true,
                    ..Default::default()
                })?;
                if !content_ids.is_empty() {
                    uow.set_binder_item_relationship(
                        &item.id,
                        &BinderItemRelationshipField::Contents,
                        &content_ids,
                    )?;
                }
                item_ids.push(item.id);
            }
            if !item_ids.is_empty() {
                uow.set_binder_relationship(
                    &binder.id,
                    &BinderRelationshipField::BinderItems,
                    &item_ids,
                )?;
            }
            binder_ids.push(binder.id);
        }
        uow.set_work_relationship(&work.id, &WorkRelationshipField::Binders, &binder_ids)?;

        // Non-undoable trunk: reuse the single shared System/Root frame (seeded by
        // `initialize_app`, or created by a prior load/new); create only if absent.
        let system_id = match uow.get_all_system()?.into_iter().next() {
            Some(system) => system.id,
            None => {
                uow.create_orphan_system(&System {
                    created_at: now,
                    updated_at: now,
                    ..Default::default()
                })?
                .id
            }
        };
        let recent = uow.create_orphan_recent_work(&RecentWork {
            created_at: now,
            updated_at: now,
            title: title.clone(),
            last_opened_at: now,
            absolute_path: dto.file_name.clone(),
            ..Default::default()
        })?;
        // Append to the existing recents rather than replacing them.
        let mut recent_ids =
            uow.get_system_relationship(&system_id, &SystemRelationshipField::RecentWorks)?;
        recent_ids.push(recent.id);
        uow.set_system_relationship(
            &system_id,
            &SystemRelationshipField::RecentWorks,
            &recent_ids,
        )?;

        let shape = if dto.is_folder {
            WorkShape::Folder
        } else {
            WorkShape::Zip
        };
        // Every Work gets its live Search surface, created eagerly alongside its
        // WorkInfo. `run_search` resolves it through `WorkInfo.search`, so a project
        // opened without one could never search. `Search`/`SearchResult` are
        // `undoable: false` and never round-trip through .skrib — this is a business
        // surface rebuilt per session, not persisted state. (The *parameters* that must
        // survive a restart live in the UI's `search.toml`, not here.)
        let search = uow.create_orphan_search(&Search {
            created_at: now,
            updated_at: now,
            ..Default::default()
        })?;
        let work_info = uow.create_orphan_work_info(&WorkInfo {
            created_at: now,
            updated_at: now,
            file_name: Some(dto.file_name.clone()),
            shape,
            ..Default::default()
        })?;
        // Per-open-Work session info: link under System.work_infos and point it
        // at its Work (the multi-Work discriminator). Append, not replace — see
        // load_work_uc.rs's `create_trunk` for the identical fix and rationale
        // (this is the second, independent occurrence of the same overwrite bug).
        let mut work_info_ids =
            uow.get_system_relationship(&system_id, &SystemRelationshipField::WorkInfos)?;
        work_info_ids.push(work_info.id);
        uow.set_system_relationship(
            &system_id,
            &SystemRelationshipField::WorkInfos,
            &work_info_ids,
        )?;
        uow.set_work_info_relationship(
            &work_info.id,
            &WorkInfoRelationshipField::Search,
            &[search.id],
        )?;
        uow.set_work_info_relationship(
            &work_info.id,
            &WorkInfoRelationshipField::Work,
            &[work.id],
        )?;

        // Reuse the single shared Root (one per process; Works hang off it).
        let root_id = match uow.get_all_root()?.into_iter().next() {
            Some(root) => root.id,
            None => {
                uow.create_orphan_root(&Root {
                    created_at: now,
                    updated_at: now,
                    ..Default::default()
                })?
                .id
            }
        };
        uow.set_root_relationship(&root_id, &RootRelationshipField::System, &[system_id])?;
        // Append, not replace — see load_work_uc.rs's `create_trunk` for the
        // identical fix and rationale (this is the second, independent occurrence
        // of the same overwrite bug).
        let mut work_ids = uow.get_root_relationship(&root_id, &RootRelationshipField::Works)?;
        work_ids.push(work.id);
        uow.set_root_relationship(&root_id, &RootRelationshipField::Works, &work_ids)?;

        uow.commit()?;

        uow.publish_new_work_event(vec![work.id], None);
        Ok(())
    }
}
